	-- Step 33: Thunder Bluff: Morrowgrain Research
	-- {npc:9076} Ghede · {npc:9087} Bashana Runetotem · {item:11020} Evergreen Pouch · {quest:3761} Un'Goro Soil · {item:11024} Evergreen Herb Casing · {item:11040} Morrowgrain
	["{npc:9076} takes the soil. {npc:9087} sells the {item:11020} (1 gold) and Packets of Tharlendris Seeds (10 silver each). With a seed packet and 2 {quest:3761} in your bags, use the pouch: it grows an {item:11024}, once every 10 minutes. Open each casing: about one in three holds 1 to 5 {item:11040}, the rest common herbs. Use the pouch whenever it is ready while you follow the rest of this guide."] = "{npc:9076} nimmt die Erde. {npc:9087} verkauft den {item:11020} (1 Gold) und Packets of Tharlendris Seeds (je 10 Silber). Mit einem Samentütchen und 2 {quest:3761} in deinen Taschen benutze den Beutel: Er lässt alle 10 Minuten eine {item:11024} wachsen. Öffne jede Hülle: Etwa jede dritte enthält 1 bis 5 {item:11040}, der Rest gewöhnliche Kräuter. Benutze den Beutel, sobald er bereit ist, während du dem Rest dieses Guides folgst.",
	-- {item:11020} Evergreen Pouch
	["{item:11020}, 1 gold"] = "{item:11020}, 1 Gold",
	-- {item:11022} Packet of Tharlendris Seeds
	["{item:11022}, 10 silver each"] = "{item:11022}, je 10 Silber",

	-- Step 34: Morrowgrain as you go
	-- {item:11040} Morrowgrain
	["{item:11040} as you go"] = "{item:11040} nebenbei",
	-- {item:11040} Morrowgrain · {npc:9087} Bashana Runetotem
	["{item:11040}: use the pouch every 10 minutes and open the casings; {npc:9087} takes it"] = "{item:11040}: Benutze den Beutel alle 10 Minuten und öffne die Hüllen; {npc:9087} nimmt es",

	-- Step 35: Bashana Runetotem: Morrowgrain Research
	-- {npc:9087} Bashana Runetotem · {area:1639} Elder Rise · {item:11040} Morrowgrain
	["{npc:9087} stands on {area:1639}. If your 10 {item:11040} are not ready yet, skip this step and go on with the cloth: the cloth steps below list the {item:11040} hand-in too."] = "{npc:9087} steht auf {area:1639}. Wenn deine 10 {item:11040} noch nicht fertig sind, überspringe diesen Schritt und mach mit dem Stoff weiter: Die Stoff-Schritte unten führen die Abgabe von {item:11040} ebenfalls auf.",

	-- Step 36: Additional Runecloth to Honored
	-- {quest:7825} Additional Runecloth
	["{quest:7825} to Honored"] = "{quest:7825} bis Wohlwollend",
	-- {quest:7825} Additional Runecloth · {item:14047} Runecloth
	["{quest:7825}: 20 {item:14047} for 50 reputation, as often as you like. Friendly to Honored is 6,000: 120 hand-ins, 2,400 {item:14047}, less what the quests gave you (a tauren starts at Friendly 1,000: 100 hand-ins; an Undead at Neutral 500 first needs 50 more to reach Friendly). Hand in every 20 you carry, one after another."] = "{quest:7825}: 20 {item:14047} für 50 Ruf, so oft du willst. Von Freundlich bis Wohlwollend sind es 6.000: 120 Abgaben, 2.400 {item:14047}, abzüglich dessen, was dir die Quests gegeben haben (ein Tauren startet bei Freundlich 1.000: 100 Abgaben; ein Untoter bei Neutral 500 braucht zuerst 50 weitere bis Freundlich). Gib alle 20, die du trägst, ab, eine Abgabe nach der anderen.",
	-- {item:11040} Morrowgrain · {npc:9087} Bashana Runetotem
	["{item:11040}, if you grow it: {npc:9087} takes it"] = "{item:11040}, falls du es anbaust: {npc:9087} nimmt es",

	-- Step 37: Additional Runecloth to Revered
	-- {quest:7825} Additional Runecloth
	["{quest:7825} to Revered"] = "{quest:7825} bis Respektvoll",
	-- {item:14047} Runecloth · {item:11040} Morrowgrain · {area:1584} Blackrock Depths · {area:340} Kargath · {npc:9017} Lord Incendius
	["Honored to Revered is 12,000: 240 hand-ins, 4,800 {item:14047}, fewer if you also hand in {item:11040}. {area:1584} pays too: Disharmony of Flame and Disharmony of Fire from Thunderheart at {area:340} ({npc:9017}, 150 in full)."] = "Von Wohlwollend bis Respektvoll sind es 12.000: 240 Abgaben, 4.800 {item:14047}, weniger, wenn du auch {item:11040} abgibst. Die {area:1584} zahlt ebenfalls: Disharmony of Flame und Disharmony of Fire von Thunderheart bei {area:340} ({npc:9017}, 150 in voller Höhe).",
	-- {item:11040} Morrowgrain
	["{item:11040}, if you grow it"] = "{item:11040}, falls du es anbaust",

	-- Step 38: Additional Runecloth to Exalted
	-- {quest:7825} Additional Runecloth
	["{quest:7825} to Exalted"] = "{quest:7825} bis Ehrfürchtig",
	-- {item:14047} Runecloth · {npc:3685} Harb Clawhoof · {area:222} Bloodhoof Village
	["Revered to Exalted is 21,000: 420 hand-ins, 8,400 {item:14047}. For The Horde! (Rend's head) and The Lord of Blackrock (Nefarian's head) pay 200 to every Horde city. At Exalted, {npc:3685} in {area:222} sells the kodos to every Horde race: 20 gold for a level 40 kodo, 200 gold for a great kodo at level 60 (Forever's prices); in Classic other races needed Exalted to buy them."] = "Von Respektvoll bis Ehrfürchtig sind es 21.000: 420 Abgaben, 8.400 {item:14047}. For The Horde! (Rends Kopf) und The Lord of Blackrock (Nefarians Kopf) geben 200 für jede Horde-Stadt. Bei Ehrfürchtig verkauft {npc:3685} in {area:222} die Kodos an jedes Horde-Volk: 20 Gold für einen Kodo der Stufe 40, 200 Gold für einen Großen Kodo auf Stufe 60 (Forevers Preise); in Classic brauchten andere Völker Ehrfürchtig, um sie zu kaufen.",
	-- {npc:3685} Harb Clawhoof
	["{npc:3685}: the kodos"] = "{npc:3685}: die Kodos",

	-- No longer in the guide (its English changed or it went away): reuse or delete.
	-- ["Dark Adepts and Shadowmages (level 58-60) drop it here; every Scourge kill here also counts toward the {object:92525} (see that guide). The Auction House works too."] = "Dunkle Adepten und Schattenmagier (Stufe 58-60) lassen ihn hier fallen; jeder getötete Gegner der Geißel hier zählt auch für {object:92525} (siehe den Guide dazu). Das Auktionshaus geht auch.",
	-- ["Dunemaul ogres (level 45-48) drop it here. The Auction House works too."] = "Oger der Dünenbrecher (Stufe 45-48) lassen ihn hier fallen. Das Auktionshaus geht auch.",
	-- ["Keep handing in {quest:7825} until {faction:81} is Exalted. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "Gib weiter {quest:7825} ab, bis du bei {faction:81} ehrfürchtig bist. {item:14047}: Dunkle Adepten und Schattenmagier (Stufe 58-60) in den {zone:1423} oder das Auktionshaus.",
	-- ["Keep handing in {quest:7825}, 20 {item:14047} at a time. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "Gib weiter {quest:7825} ab, jeweils 20 {item:14047}. {item:14047}: Dunkle Adepten und Schattenmagier (Stufe 58-60) in den {zone:1423} oder das Auktionshaus.",
	-- ["Kolkar centaur (level 30-33) drop it here. The Auction House works too."] = "Zentauren der Kolkar (Stufe 30-33) lassen ihn hier fallen. Das Auktionshaus geht auch.",
	-- ["Venture Co. Enforcers at the {area:381} (level 16-17) drop it here. The Auction House works too."] = "Vollstrecker der Venture Co. bei der {area:381} (Stufe 16-17) lassen ihn hier fallen. Das Auktionshaus geht auch.",
	-- ["{npc:14728} takes cloth for {faction:81} in {faction:81}. The first donations of Wool, Silk, Mageweave and {item:14047} (60 cloth each) are done once and give the most reputation per cloth; after them, {quest:7825} repeats until Exalted. Exalted with another race's city lets you buy that race's mounts. Forever's Legacy Diplomat perk increases reputation gains."] = "{npc:14728} nimmt in {faction:81} Stoff für {faction:81} an. Die ersten Spenden von Wollstoff, Seidenstoff, Magiestoff und {item:14047} (je 60 Stoff) gibt es nur einmal, und sie bringen den meisten Ruf pro Stoff; danach wiederholt sich {quest:7825} bis Ehrfürchtig. Bist du bei der Hauptstadt eines anderen Volkes ehrfürchtig, kannst du dessen Reittiere kaufen. Der Vermächtnis-Vorteil „Diplomat“ von Forever erhöht den Rufgewinn.",
	-- ["{npc:14728}: {item:14047} delivered"] = "{npc:14728}: {item:14047} abgeliefert",
	-- ["{quest:7825} takes 20 {item:14047} per turn-in and repeats as often as you like. Bring {item:14047} in multiples of 20 and hand them all in at once, one turn-in after another. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "{quest:7825} nimmt 20 {item:14047} pro Abgabe und lässt sich beliebig oft wiederholen. Bring {item:14047} in Vielfachen von 20 mit und gib alles auf einmal ab, eine Abgabe nach der anderen. {item:14047}: Dunkle Adepten und Schattenmagier (Stufe 58-60) in den {zone:1423} oder das Auktionshaus.",
}
